def steward_edge(row: ExpectedOccurrence) -> tuple[str,str] | None:
    if row.test == CANCEL and row.branch == 'loaded':
        return 'original', 'continuation'
    if row.test in HOUSING:
        if row.branch in {'replay','food','cooldown',*(f'manual_{n}' for n in range(4))}:
            return 'original','first_housed'
        if row.branch in {f'restored_{n}' for n in range(4)}:
            return 'manual_'+row.branch[-1], 'manual'
    return None
